const std = @import("std"); const abi = @import("abi_bindings"); const narrow = @import("narrow_unsafe"); pub const Word = usize; pub const bits_per_long: u32 = @intCast(@bitSizeOf(Word)); pub fn wordCount(nbits: u32) u32 { return if (nbits == 0) 0 else (nbits + bits_per_long - 1) / bits_per_long; } pub fn lastWordMask(nbits: u32) Word { if (nbits == 0) return 0; const rem = nbits % bits_per_long; if (rem == 0) return ~@as(Word, 0); return ~@as(Word, 0) >> @intCast(bits_per_long - rem); } pub fn viewFromWords(backing: []const Word, nbits: u32) abi.BitmapView { std.debug.assert(backing.len == wordCount(nbits)); return .{ .words_addr = if (backing.len == 0) 0 else narrow.addressOf(&backing[0]), .nbits = nbits, .word_count = @intCast(backing.len), }; } pub fn isValid(view: abi.BitmapView) bool { const expected = wordCount(view.nbits); if (view.word_count != expected) return false; return expected == 0 or view.words_addr != 0; } fn wordSlice(view: abi.BitmapView) []align(1) const Word { std.debug.assert(view.word_count != 0); return narrow.constSliceAt(Word, .raw_pointer_bridge, view.words_addr, view.word_count) catch unreachable; } pub fn testBit(view: abi.BitmapView, bit: u32) bool { if (!isValid(view) or bit >= view.nbits) return false; if (view.word_count == 0) return false; const slice = wordSlice(view); const word_index = bit / bits_per_long; const bit_index = bit % bits_per_long; return ((slice[word_index] >> @intCast(bit_index)) & 1) != 0; } pub fn firstSet(view: abi.BitmapView) u32 { if (!isValid(view)) return 0; if (view.word_count == 0) return view.nbits; const slice = wordSlice(view); for (slice, 0..) |raw_word, index| { const masked = if (index + 1 == slice.len) raw_word & lastWordMask(view.nbits) else raw_word; if (masked != 0) { const offset: u32 = @intCast(@ctz(masked)); return @intCast(index * bits_per_long + offset); } } return view.nbits; } pub fn firstZero(view: abi.BitmapView) u32 { if (!isValid(view)) return 0; if (view.word_count == 0) return view.nbits; const slice = wordSlice(view); for (slice, 0..) |raw_word, index| { var masked = ~raw_word; if (index + 1 == slice.len) masked &= lastWordMask(view.nbits); if (masked != 0) { const offset: u32 = @intCast(@ctz(masked)); return @intCast(index * bits_per_long + offset); } } return view.nbits; } pub fn weight(view: abi.BitmapView) u32 { if (!isValid(view)) return 0; if (view.word_count == 0) return 0; var total: u32 = 0; const slice = wordSlice(view); for (slice, 0..) |raw_word, index| { const masked = if (index + 1 == slice.len) raw_word & lastWordMask(view.nbits) else raw_word; total += @intCast(@popCount(masked)); } return total; } pub fn summarize(view: abi.BitmapView) abi.BitmapSummary { if (!isValid(view)) return .{ .first_set = 0, .first_zero = 0, .weight = 0, .reserved = 0 }; return .{ .first_set = firstSet(view), .first_zero = firstZero(view), .weight = weight(view), .reserved = 0, }; } test "phase3 bitmap view helpers stay bounded and predictable" { var backing = [_]Word{ (@as(Word, 1) << 1) | (@as(Word, 1) << 5) | (@as(Word, 1) << 63), (@as(Word, 1) << 4) | (@as(Word, 1) << 9), }; const view = viewFromWords(backing[0..], bits_per_long + 10); const summary = summarize(view); try std.testing.expect(isValid(view)); try std.testing.expectEqual(@as(u32, 2), wordCount(bits_per_long + 10)); try std.testing.expectEqual(@as(u32, 1), firstSet(view)); try std.testing.expectEqual(@as(u32, 0), firstZero(view)); try std.testing.expectEqual(@as(u32, 5), weight(view)); try std.testing.expect(testBit(view, 63)); try std.testing.expect(!testBit(view, 4)); try std.testing.expectEqual(@as(u32, 1), summary.first_set); try std.testing.expectEqual(@as(u32, 0), summary.first_zero); try std.testing.expectEqual(@as(u32, 5), summary.weight); } test "phase3 bitmap view empty sentinel behavior stays explicit" { const empty = viewFromWords(&.{}, 0); const summary = summarize(empty); try std.testing.expect(isValid(empty)); try std.testing.expectEqual(@as(u32, 0), firstSet(empty)); try std.testing.expectEqual(@as(u32, 0), firstZero(empty)); try std.testing.expectEqual(@as(u32, 0), weight(empty)); try std.testing.expectEqual(@as(u32, 0), summary.weight); }
